Example: voidreportPerSecond(std::ostream&output,Progress*progress){
progress->reportRegularly(boost::chrono::seconds(1),[&output](constReport&report,doubleage){
output<<(boost::format("%s%.0f%%\n")%report.name%(100.0*report.completion));
});
}

Example: voidreportChanges(std::ostream&output,Progress*progress){
progress->reportChanges(boost::chrono::seconds(1),[&output](constReport&report){
output<<(boost::format("%s%.0f%%\n")%report.name%(100.0*report.completion));
});
}

Example: //functionthatdoeslotsofworkandoptionallyreportsitsprogress.
voidworker(Progress::Ptrprogress){
for(size_ti=0;i<1000000;++i){
do_some_work();
if(progress)
progress->update((double)i/1000000);
}
if(progress)
progress->finished(1.0);
}

//Startaworkerandprovideawayforittoreportitsprogress
Progress::Ptrprogress=Progress::instance();
boost::thread_tworker(worker,progress);

//Reportprogressonstandarderroreachtimeitchanges,butnotmorethanonceevery10seconds
progress->reportChanges(boost::chrono::seconds(10),[](constProgress::Report&rpt)->bool{
std::cout<<rpt.phase<<":"<<(100*rpt.completion)<<"percentcompleted\n";
returntrue;//keeplisteninguntiltaskisfinished
});

//Orreportprogressevery10secondswhetheritchangedornot
progress->reportRegularly(boost::chrono::seconds(10),[](constProgress::Report&rpt,doubleage)->bool{
std::cout<<rpt.phase<<":"<<(100*rpt.completion)<<"percentcompleted\n";
returntrue;//keeplisteninguntiltaskisfinished
});

//Orquerytheprogressinaneventloop
while(!progress->isFinished()){
Progress::Reportrpt=progress->reportLatest().first;
std::cout<<rpt.phase<<":"<<(100*rpt.completion)<<"percentcompleted\n";
do_other_stuff();
}
